    @Test
    fun futabaOnlyDataIsWrittenByteForByteAsBefore() {
        val actual = FutabaOnlyEncodings.all()
        assertEquals(golden.keys, actual.keys)
        golden.forEach { (name, expected) ->
            assertEquals(expected, actual.getValue(name), name)
            assertEquals(expected.encodeToByteArray().size, actual.getValue(name).encodeToByteArray().size, "$name bytes")
        }
    }

    /** The backup file of today restores to the same records; AM-B5 runs this on a file the new version writes too. */
    @Test
    fun aFutabaOnlyBackupRestoresTheSameRecords() {
        assertEquals(FutabaOnlyEncodings.backup, decodeCompatSettingsBackup(golden.getValue("backup")))
    }
